if (!msg.payload) {
    node.status({fill:"red", shape:"ring", text:"No data received"});
    node.error('No payload received from sites API');
    return null;
}

try {
    msg.sites = msg.payload;
    msg.processingStats = {
        sitesReceived: msg.sites.length,
        timestamp: new Date().toISOString()
    };

    node.status({fill:"green", shape:"dot", text:`Stored ${msg.sites.length} sites`});
    return msg;
} catch(err) {
    node.status({fill:"red", shape:"ring", text:"Processing error"});
    node.error('Error processing sites data: ' + err.message);
    return null;
}

console.log('Processing devices data...');

if (!msg.payload) {
    node.status({fill:"red", shape:"ring", text:"No devices data"});
    node.error('No payload received from devices API');
    return null;
}

try {
    msg.devices = Array.isArray(msg.payload.data) ? msg.payload.data : 
                  Array.isArray(msg.payload) ? msg.payload : [];

    msg.processingStats.devicesReceived = msg.devices.length;

    node.status({fill:"green", shape:"dot", text:`Stored ${msg.devices.length} devices`});
    return msg;
} catch(err) {
    node.status({fill:"red", shape:"ring", text:"Processing error"});
    node.error('Error processing devices data: ' + err.message);
    return null;
}

node.status({fill:"blue", shape:"dot", text:"Processing..."});

try {
    // Validate input data
    if (!Array.isArray(msg.payload) || !Array.isArray(msg.sites) || !Array.isArray(msg.devices)) {
        throw new Error('Invalid data structure received');
    }

    // Process suspended clients
    const suspendedClients = msg.payload.filter(client => client.hasSuspendedService === true);
    const suspendedClientIds = new Set(suspendedClients.map(client => client.id.toString()));

    // Process sites
    const relevantSites = msg.sites.filter(site => {
        const clientId = site.ucrm?.client?.id;
        return clientId && suspendedClientIds.has(clientId);
    });

    const siteMap = new Map(relevantSites.map(site => [site.id, site]));

    // Process devices
    const relevantDevices = msg.devices
        .filter(device => {
            const siteId = device.identification?.site?.id;
            const isRouter = device.identification?.role === 'router';
            return siteId && siteMap.has(siteId) && isRouter;
        })
        .map(device => ({
            device_id: device.identification.id,
            device_name: device.identification.name,
            device_role: device.identification.role,
            device_status: device.overview.status,
            ip_address: device.ipAddress,
            site_id: device.identification.site.id,
            site_name: siteMap.get(device.identification.site.id).identification.name,
            client_id: siteMap.get(device.identification.site.id).ucrm.client.id,
            client_name: siteMap.get(device.identification.site.id).ucrm.client.name
        }));

    // Update processing stats
    msg.processingStats.suspendedClients = suspendedClients.length;
    msg.processingStats.relevantSites = relevantSites.length;
    msg.processingStats.relevantDevices = relevantDevices.length;

    msg.payload = relevantDevices;

    node.status({fill:"green", shape:"dot", text:`Processed ${relevantDevices.length} devices`});
    return msg;

} catch(err) {
    node.status({fill:"red", shape:"ring", text:"Error: " + err.message});
    node.error('Processing error: ' + err.message);
    return null;
}

// Create process summary
const summary = {
    timestamp: new Date().toISOString(),
    stats: msg.processingStats,
    duration: `${msg.processingStats.totalDuration / 1000} seconds`,
    status: 'Complete'
};

// Store summary in global context
context.global.set('lastProcessRun', summary);

return { payload: summary };

// Create formatted error message
const errorMsg = {
    timestamp: new Date().toISOString(),
    error: msg.error.message || 'Unknown error',
    node: msg.error.source?.name || 'Unknown node',
    details: msg.error.toString(),
    payload: msg.payload
};

// Store in flow context for tracking
flow.set('lastError', errorMsg);

return { payload: errorMsg };

// Prepare MySQL Insert Function
if (!Array.isArray(msg.payload) || msg.payload.length === 0) {
    node.status({ fill: "yellow", shape: "ring", text: "No data to insert" });
    return null;
}

try {
    // Prepare batch insert
    const values = msg.payload.map(device => [
        device.device_id,
        device.device_name,
        device.device_role,
        device.device_status,
        device.ip_address,
        device.site_id,
        device.site_name,
        device.client_id,
        device.client_name
    ]);

    // First output - MySQL query
    const mysqlMsg = {
        topic: 'INSERT INTO suspended_router_devices ' +
            '(device_id, device_name, device_role, device_status, ' +
            'ip_address, site_id, site_name, client_id, client_name) ' +
            'VALUES ?',
        payload: [values],
        processingStats: msg.processingStats // Preserve the stats
    };

    // Add completion time to stats
    mysqlMsg.processingStats.completionTime = new Date().toISOString();
    mysqlMsg.processingStats.totalDuration = Date.now() - new Date(msg.processingTime?.startTime || Date.now()).getTime();

    node.status({ fill: "green", shape: "dot", text: `Ready to insert ${values.length} records` });
    return mysqlMsg;

} catch (err) {
    node.status({ fill: "red", shape: "ring", text: "Error preparing insert" });
    node.error('Error preparing MySQL insert: ' + err.message);
    return null;
}

// Store the original payload and stats for later use
msg.originalPayload = msg.payload;
msg.originalStats = msg.processingStats;

// Set up truncate command
msg.topic = 'TRUNCATE TABLE suspended_router_devices';
node.status({fill:"blue", shape:"dot", text:"Preparing to truncate table"});

return msg;

// Restore the original payload and stats
msg.payload = msg.originalPayload;
msg.processingStats = msg.originalStats;

// Clean up temporary storage
delete msg.originalPayload;
delete msg.originalStats;

node.status({fill:"green", shape:"dot", text:"Table truncated"});

return msg;

// Only format the email content, remove email property settings
function formatDate(dateStr) {
