}

// Add debug logging to inspect the incoming message
console.log('Incoming message structure:', JSON.stringify(msg, null, 2));

// Ensure processingStats exists
const stats = msg.processingStats || {};
console.log('Processing stats:', stats);

// Create HTML email content with safe access to properties
const htmlContent = `
