// Only set the payload to the HTML content
msg.payload = htmlContent;

return msg;

// Initialize processing stats
const processStats = {
    startTime: new Date().toISOString(),
    suspendedIPs: 0,
    currentBlockedIPs: 0,
    ipsToAdd: 0,
    ipsToRemove: 0,
    completedAdds: 0,
    completedRemoves: 0,
    status: 'Started'
};

// Store in flow context
flow.set('processStats', processStats);

// Set initial status
node.status({fill:"blue", shape:"dot", text:"Process started"});

return msg;

msg.topic = 'SELECT ip_address FROM suspended_router_devices where ip_address is not null;';

node.status({fill:"blue", shape:"dot", text:"Querying suspended IPs"});

return msg;

// Get process stats
let stats = flow.get('processStats') || {};

// Store suspended IPs in flow context
let suspendedIPs = msg.payload.map(row => row.ip_address);
flow.set('suspendedIPs', suspendedIPs);

// Update stats
stats.suspendedIPs = suspendedIPs.length;
stats.status = 'Retrieved suspended IPs';
flow.set('processStats', stats);

// Update status
node.status({fill:"blue", shape:"dot", text:`Found ${suspendedIPs.length} suspended IPs`});

return msg;

// Get process stats
let stats = flow.get('processStats') || {};

// Get suspended IPs from flow context 
let suspendedIPs = flow.get('suspendedIPs') || [];

// Extract current blocked entries 
let allEntries = msg.payload || [];

// Filter for BLOCKED_USERS and extract IPs 
let blockedEntries = allEntries.filter(entry => entry.list === 'BLOCKED_USERS');
let blockedIPs = blockedEntries.map(entry => entry.address);

// Find IPs to add (in suspended but not in blocked) 
let ipsToAdd = suspendedIPs.filter(ip => !blockedIPs.includes(ip));

// Find entries to remove (in blocked but not in suspended) 
let entriesToRemove = blockedEntries.filter(entry =>
    !suspendedIPs.includes(entry.address)
);

// Store in flow context 
flow.set('ipsToAdd', ipsToAdd);
flow.set('entriesToRemove', entriesToRemove);

// Update process stats
stats.currentBlockedIPs = blockedIPs.length;
stats.ipsToAdd = ipsToAdd.length;
stats.ipsToRemove = entriesToRemove.length;
stats.status = 'Comparison completed';
flow.set('processStats', stats);

// Debug logging 
node.warn('IPs to add: ' + JSON.stringify(ipsToAdd));
node.warn('Entries to remove: ' + JSON.stringify(entriesToRemove));

// Update status
node.status({
    fill: "blue",
    shape: "dot",
    text: `To process: Add ${ipsToAdd.length}, Remove ${entriesToRemove.length}`
});

// Create message for next action 
let outMsg = {
    phase: 'remove',  // Start with removes
    payload: null
};

// If there are entries to remove, start with first one 
if (entriesToRemove.length > 0) {
    outMsg.payload = entriesToRemove[0];
    return outMsg;
}
// If no removes but adds exist, switch to add phase 
else if (ipsToAdd.length > 0) {
    outMsg.phase = 'add';
    outMsg.payload = ipsToAdd[0];
    return outMsg;
}

// Nothing to do
if (ipsToAdd.length === 0 && entriesToRemove.length === 0) {
    stats.status = 'Completed - No changes needed';
    stats.endTime = new Date().toISOString();
    flow.set('processStats', stats);

    return {
        trigger: 'generate_summary',
        payload: {
            message: 'No changes required'
        }
    };
}

// Nothing to do 
return null;

if (!msg || !msg.payload || !msg.payload['.id']) {
    node.warn('Invalid remove command input');
    return null;
}

let newMsg = {
    phase: 'remove',  // Maintain phase
    topic: 'write',
    payload: [
        '/ip/firewall/address-list/remove',
        '=.id=' + msg.payload['.id']
    ]
};

node.status({fill:"blue", shape:"dot", text:`Removing entry ID: ${msg.payload['.id']}`});
return newMsg;

if (!msg || !msg.payload || typeof msg.payload !== 'string') {
    node.warn('Invalid add command input');
    return null;
}

let newMsg = {
    phase: 'add',  // Maintain phase
    topic: 'write',
    payload: [
        '/ip/firewall/address-list/add',
        '=address=' + msg.payload,
        '=list=BLOCKED_USERS',
        '=comment=added by nodered'
    ]
};

node.status({fill:"blue", shape:"dot", text:`Adding IP: ${msg.payload}`});
return newMsg;

// Get process stats
let stats = flow.get('processStats') || {};

let phase = msg.phase || 'remove';
let entriesToRemove = flow.get('entriesToRemove') || [];
let ipsToAdd = flow.get('ipsToAdd') || [];

// Update completion counts
if (phase === 'remove') {
    stats.completedRemoves++;
} else {
    stats.completedAdds++;
}

// If in remove phase
if (phase === 'remove') {
    entriesToRemove.shift();
    flow.set('entriesToRemove', entriesToRemove);

    if (entriesToRemove.length > 0) {
        stats.status = `Removing entries: ${stats.completedRemoves}/${stats.ipsToRemove}`;
        node.status({fill:"blue", shape:"dot", text:stats.status});
        flow.set('processStats', stats);
        return {
            phase: 'remove',
            payload: entriesToRemove[0]
        };
    }

    if (ipsToAdd.length > 0) {
        stats.status = 'Starting add phase';
        node.status({fill:"blue", shape:"dot", text:stats.status});
        flow.set('processStats', stats);
        return {
            phase: 'add',
            payload: ipsToAdd[0]
        };
    }
}

// If in add phase
if (phase === 'add') {
    ipsToAdd.shift();
    flow.set('ipsToAdd', ipsToAdd);

    if (ipsToAdd.length > 0) {
        stats.status = `Adding IPs: ${stats.completedAdds}/${stats.ipsToAdd}`;
        node.status({fill:"blue", shape:"dot", text:stats.status});
        flow.set('processStats', stats);
        return {
            phase: 'add',
            payload: ipsToAdd[0]
        };
    }
}

// Process complete
stats.status = 'Completed';
stats.endTime = new Date().toISOString();
flow.set('processStats', stats);
node.status({fill:"green", shape:"dot", text:"Process complete"});

// Return message to trigger summary generation
return { trigger: 'generate_summary' };

// Update process stats with error
let stats = flow.get('processStats') || {};
stats.status = 'Error: ' + (msg.error?.message || 'Unknown error');
stats.endTime = new Date().toISOString();
flow.set('processStats', stats);

// Create error summary email
const htmlContent = `
<h2>MikroTik Sync Process Error</h2>
<p>An error occurred during the synchronization process:</p>

<div style="background-color: #fff3f3; padding: 15px; border-left: 4px solid #dc3545; margin: 10px 0;">
    <strong>Error Details:</strong><br>
    ${msg.error?.message || 'Unknown error'}<br>
    Location: ${msg.error?.source?.name || 'Unknown location'}
</div>

<h3>Process Details:</h3>
<ul>
    <li>Start Time: ${new Date(stats.startTime).toLocaleString()}</li>
    <li>Error Time: ${new Date(stats.endTime).toLocaleString()}</li>
    <li>Last Status: ${stats.status}</li>
</ul>

<p><em>Please check the Node-RED logs for more details.</em></p>
`;

msg.payload = htmlContent;

return msg;
